diff --git a/qualifier/Q2/paid-route.ts b/qualifier/Q2/paid-route.ts
new file mode 100644
--- /dev/null
+++ b/qualifier/Q2/paid-route.ts
@@ -0,0 +1,188 @@
+// Qualifier Q2: an x402 paid route.
+// Unpaid: 402 with the payment requirements in the body.
+// Paid: verify, then settle through the facilitator, then 200 with X-PAYMENT-RESPONSE.
+// A failed verification or settlement is a 402, never a 200.
+
+export interface PaymentRequirements {
+  scheme: string;
+  network: string;
+  maxAmountRequired: string;
+  resource: string;
+  description: string;
+  mimeType: string;
+  payTo: string;
+  maxTimeoutSeconds: number;
+  asset: string;
+  extra?: Record<string, unknown>;
+}
+
+export interface Facilitator {
+  verify(payment: unknown, requirements: PaymentRequirements): Promise<unknown> | unknown;
+  settle(payment: unknown, requirements: PaymentRequirements): Promise<unknown> | unknown;
+}
+
+export interface PaidRouteOptions {
+  price: string | number;
+  payTo: string;
+  network: string;
+  facilitator: Facilitator;
+  asset?: string;
+  resource?: string;
+  description?: string;
+  maxTimeoutSeconds?: number;
+  scheme?: string;
+  extra?: Record<string, unknown>;
+  handler?: (request: Request, settlement: unknown) => Promise<Response> | Response;
+}
+
+const BASE_USDC = "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913";
+
+function truthy(value: unknown, keys: string[]): boolean {
+  if (value === true) return true;
+  if (value === false || value === null || value === undefined) return false;
+  if (typeof value === "object") {
+    for (const key of keys) {
+      const v = (value as Record<string, unknown>)[key];
+      if (v === true) return true;
+    }
+  }
+  return false;
+}
+
+function settlementSucceeded(value: unknown): boolean {
+  if (value === true) return true;
+  if (value === false || value === null || value === undefined) return false;
+  if (typeof value === "object") {
+    const record = value as Record<string, unknown>;
+    if (record.success === false) return false;
+    if (record.success === true || record.settled === true) return true;
+    if (typeof record.transaction === "string" && record.transaction.length > 0) return true;
+  }
+  return false;
+}
+
+function b64decode(text: string): string {
+  if (typeof atob === "function") return atob(text);
+  // Node without atob on very old versions.
+  return Buffer.from(text, "base64").toString("binary");
+}
+
+function b64encode(text: string): string {
+  if (typeof btoa === "function") return btoa(text);
+  return Buffer.from(text, "binary").toString("base64");
+}
+
+function json(body: unknown, status: number, extraHeaders: Record<string, string> = {}): Response {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { "content-type": "application/json", ...extraHeaders },
+  });
+}
+
+export function createPaidRoute(options: PaidRouteOptions): (request: Request) => Promise<Response> {
+  const {
+    price,
+    payTo,
+    network,
+    facilitator,
+    asset = BASE_USDC,
+    description = "paid call",
+    maxTimeoutSeconds = 60,
+    scheme = "exact",
+    extra,
+    handler,
+  } = options;
+
+  if (!payTo || typeof payTo !== "string") throw new Error("payTo must be a non empty string");
+  if (!network || typeof network !== "string") throw new Error("network must be a non empty string");
+  if (!facilitator || typeof facilitator.verify !== "function" || typeof facilitator.settle !== "function") {
+    throw new Error("facilitator must expose verify and settle");
+  }
+  const amount = typeof price === "number" ? String(price) : price;
+  if (typeof amount !== "string" || !/^[0-9]+$/.test(amount)) {
+    throw new Error("price must be an integer string in atomic units");
+  }
+
+  return async function paidRoute(request: Request): Promise<Response> {
+    // The v1 contract this bundle names uses X-PAYMENT; a v2 client sends
+    // PAYMENT-SIGNATURE. Accept either so a caller is never refused on the
+    // header name alone.
+    const requirements: PaymentRequirements = {
+      scheme,
+      network,
+      maxAmountRequired: amount,
+      resource: options.resource ?? request.url,
+      description,
+      mimeType: "application/json",
+      payTo,
+      maxTimeoutSeconds,
+      asset,
+      ...(extra ? { extra } : {}),
+    };
+
+    const header =
+      request.headers.get("x-payment") ?? request.headers.get("payment-signature");
+    if (!header) {
+      return json(
+        {
+          x402Version: 1,
+          error: "payment required",
+          accepts: [requirements],
+        },
+        402,
+      );
+    }
+
+    let payment: unknown;
+    try {
+      payment = JSON.parse(b64decode(header.trim()));
+    } catch {
+      return json({ x402Version: 1, error: "invalid X-PAYMENT header", accepts: [requirements] }, 402);
+    }
+
+    let verification: unknown;
+    try {
+      verification = await facilitator.verify(payment, requirements);
+    } catch (error) {
+      return json(
+        { x402Version: 1, error: "verification failed", detail: String(error), accepts: [requirements] },
+        402,
+      );
+    }
+    if (!truthy(verification, ["isValid", "valid", "verified", "success"])) {
+      return json({ x402Version: 1, error: "payment not verified", accepts: [requirements] }, 402);
+    }
+
+    let settlement: unknown;
+    try {
+      settlement = await facilitator.settle(payment, requirements);
+    } catch (error) {
+      return json(
+        { x402Version: 1, error: "settlement failed", detail: String(error), accepts: [requirements] },
+        402,
+      );
+    }
+    if (!settlementSucceeded(settlement)) {
+      return json({ x402Version: 1, error: "payment not settled", accepts: [requirements] }, 402);
+    }
+
+    const receipt =
+      settlement && typeof settlement === "object"
+        ? { success: true, ...(settlement as Record<string, unknown>) }
+        : { success: true, result: settlement };
+    const receiptHeader = b64encode(JSON.stringify(receipt));
+
+    if (handler) {
+      const response = await handler(request, settlement);
+      const headers = new Headers(response.headers);
+      headers.set("x-payment-response", receiptHeader);
+      headers.set("payment-response", receiptHeader);
+      return new Response(response.body, { status: response.status, headers });
+    }
+
+    return json({ ok: true, paid: true }, 200, {
+      "x-payment-response": receiptHeader,
+      "payment-response": receiptHeader,
+    });
+  };
+}
diff --git a/qualifier/Q2/paid-route.test.ts b/qualifier/Q2/paid-route.test.ts
new file mode 100644
--- /dev/null
+++ b/qualifier/Q2/paid-route.test.ts
@@ -0,0 +1,213 @@
+// A4: the route answers 402 when unpaid, verifies then settles when paid, answers
+// 200 with X-PAYMENT-RESPONSE only after a real settlement, and never charges twice.
+import test from "node:test";
+import assert from "node:assert/strict";
+
+import { createPaidRoute } from "./paid-route.ts";
+
+const PAY_TO = "0x1111111111111111111111111111111111111111";
+const ASSET = "0x2222222222222222222222222222222222222222";
+
+function paidHeader(payload: unknown = { x402Version: 1, scheme: "exact" }): string {
+  return Buffer.from(JSON.stringify(payload), "binary").toString("base64");
+}
+
+function stubFacilitator(
+  verifyResult: unknown = { isValid: true },
+  settleResult: unknown = { success: true, transaction: "0xdead", network: "base", payer: "0xabc" },
+) {
+  const calls: string[] = [];
+  return {
+    calls,
+    facilitator: {
+      async verify() {
+        calls.push("verify");
+        return verifyResult;
+      },
+      async settle() {
+        calls.push("settle");
+        return settleResult;
+      },
+    },
+  };
+}
+
+function route(extra: Record<string, unknown> = {}) {
+  const { calls, facilitator } = stubFacilitator();
+  const fn = createPaidRoute({
+    price: "5000",
+    payTo: PAY_TO,
+    network: "eip155:8453",
+    asset: ASSET,
+    facilitator,
+    ...extra,
+  });
+  return { fn, calls };
+}
+
+test("A4 an unpaid request is a 402 with the payment requirements", async () => {
+  const { fn, calls } = route();
+  const res = await fn(new Request("https://agent.example/patch", { method: "POST" }));
+  assert.equal(res.status, 402);
+  assert.match(res.headers.get("content-type") ?? "", /application\/json/);
+  const body = await res.json();
+  assert.equal(body.x402Version, 1);
+  assert.equal(body.accepts.length, 1);
+  assert.equal(body.accepts[0].scheme, "exact");
+  assert.equal(body.accepts[0].network, "eip155:8453");
+  assert.equal(body.accepts[0].maxAmountRequired, "5000");
+  assert.equal(body.accepts[0].payTo, PAY_TO);
+  assert.equal(body.accepts[0].asset, ASSET);
+  assert.equal(body.accepts[0].resource, "https://agent.example/patch");
+  assert.equal(calls.length, 0, "nothing is verified before a payment is offered");
+});
+
+test("A4 a verified and settled payment is a 200 with X-PAYMENT-RESPONSE", async () => {
+  const { fn, calls } = route();
+  const res = await fn(
+    new Request("https://agent.example/patch", { method: "POST", headers: { "X-PAYMENT": paidHeader() } }),
+  );
+  assert.equal(res.status, 200);
+  const receiptHeader = res.headers.get("x-payment-response");
+  assert.ok(receiptHeader, "X-PAYMENT-RESPONSE header is set");
+  const receipt = JSON.parse(Buffer.from(receiptHeader!, "base64").toString("binary"));
+  assert.equal(receipt.success, true);
+  assert.equal(receipt.transaction, "0xdead");
+  assert.equal(receipt.network, "base");
+  assert.deepEqual(calls, ["verify", "settle"], "verify runs before settle, once each");
+});
+
+test("A4 a payment that does not verify is a 402 and is never settled", async () => {
+  const { facilitator, calls } = stubFacilitator({ isValid: false });
+  const fn = createPaidRoute({
+    price: "5000",
+    payTo: PAY_TO,
+    network: "eip155:8453",
+    asset: ASSET,
+    facilitator,
+  });
+  const res = await fn(new Request("https://agent.example/patch", { headers: { "X-PAYMENT": paidHeader() } }));
+  assert.equal(res.status, 402);
+  assert.equal(res.headers.get("x-payment-response"), null);
+  assert.deepEqual(calls, ["verify"]);
+});
+
+test("A4 a verification that throws is a 402", async () => {
+  const fn = createPaidRoute({
+    price: "5000",
+    payTo: PAY_TO,
+    network: "eip155:8453",
+    asset: ASSET,
+    facilitator: {
+      verify() {
+        throw new Error("facilitator down");
+      },
+      settle() {
+        return { success: true };
+      },
+    },
+  });
+  const res = await fn(new Request("https://agent.example/patch", { headers: { "X-PAYMENT": paidHeader() } }));
+  assert.equal(res.status, 402);
+  const body = await res.json();
+  assert.match(body.error, /verification failed/);
+});
+
+test("A4 a settlement that fails is a 402 with no success receipt", async () => {
+  const { facilitator } = stubFacilitator({ isValid: true }, { success: false, error: "insufficient funds" });
+  const fn = createPaidRoute({
+    price: "5000",
+    payTo: PAY_TO,
+    network: "eip155:8453",
+    asset: ASSET,
+    facilitator,
+  });
+  const res = await fn(new Request("https://agent.example/patch", { headers: { "X-PAYMENT": paidHeader() } }));
+  assert.equal(res.status, 402);
+  assert.equal(res.headers.get("x-payment-response"), null);
+});
+
+test("A4 a settlement that reports failure is a 402 even when it carries a transaction", async () => {
+  const { facilitator } = stubFacilitator({ isValid: true }, { success: false, transaction: "0xdead" });
+  const fn = createPaidRoute({
+    price: "5000",
+    payTo: PAY_TO,
+    network: "eip155:8453",
+    asset: ASSET,
+    facilitator,
+  });
+  const res = await fn(new Request("https://agent.example/patch", { headers: { "X-PAYMENT": paidHeader() } }));
+  assert.equal(res.status, 402);
+  assert.equal(res.headers.get("x-payment-response"), null);
+});
+
+test("A4 a settlement that throws is a 402", async () => {
+  const fn = createPaidRoute({
+    price: "5000",
+    payTo: PAY_TO,
+    network: "eip155:8453",
+    asset: ASSET,
+    facilitator: {
+      verify() {
+        return { isValid: true };
+      },
+      settle() {
+        throw new Error("broadcast failed");
+      },
+    },
+  });
+  const res = await fn(new Request("https://agent.example/patch", { headers: { "X-PAYMENT": paidHeader() } }));
+  assert.equal(res.status, 402);
+});
+
+test("A4 a malformed payment header is a 402", async () => {
+  const { fn, calls } = route();
+  const res = await fn(new Request("https://agent.example/patch", { headers: { "X-PAYMENT": "not base64 json" } }));
+  assert.equal(res.status, 402);
+  assert.equal(calls.length, 0);
+});
+
+test("A4 a handler runs only after settlement and keeps the receipt header", async () => {
+  const { fn, calls } = route({
+    handler() {
+      calls.push("handler");
+      return new Response(JSON.stringify({ patch: "diff --git a/x b/x" }), {
+        status: 200,
+        headers: { "content-type": "application/json" },
+      });
+    },
+  });
+  const res = await fn(new Request("https://agent.example/patch", { headers: { "X-PAYMENT": paidHeader() } }));
+  assert.equal(res.status, 200);
+  const body = await res.json();
+  assert.match(body.patch, /diff --git/);
+  assert.ok(res.headers.get("x-payment-response"));
+  assert.deepEqual(calls, ["verify", "settle", "handler"]);
+});
+
+test("A4 invalid options are refused at construction", () => {
+  const bad = (opts: Record<string, unknown>) =>
+    createPaidRoute({
+      price: "5000",
+      payTo: PAY_TO,
+      network: "eip155:8453",
+      facilitator: { verify: () => true, settle: () => true } as never,
+      ...opts,
+    } as never);
+  assert.throws(() => bad({ payTo: "" }));
+  assert.throws(() => bad({ network: "" }));
+  assert.throws(() => bad({ price: "0.005" }));
+  assert.throws(() => bad({ price: "-1" }));
+  assert.throws(() => bad({ facilitator: {} }));
+});
+
+test("A4 a v2 client header name is accepted and both receipt headers are set", async () => {
+  const facilitator = { verify: async () => ({ isValid: true }), settle: async () => ({ success: true, transaction: "0xabc" }) };
+  const fn = createPaidRoute({ price: "1000", payTo: "0xpay", network: "base", facilitator });
+  const res = await fn(
+    new Request("https://agent.example/paid", { headers: { "PAYMENT-SIGNATURE": paidHeader() } }),
+  );
+  assert.equal(res.status, 200);
+  assert.ok(res.headers.get("x-payment-response"), "v1 receipt header");
+  assert.ok(res.headers.get("payment-response"), "v2 receipt header");
+});
